// Import necessary libraries
import BpmnJS from 'bpmn-js/lib/Modeler';

// Create a new BPMN modeler instance
const bpmnModeler = new BpmnJS({
  container: '#canvas'
});

// Define the BPMN XML with a boundary event and association
const bpmnXML = `<?xml version="1.0" encoding="UTF-8"?>
<definitions xmlns="http://www.omg.org/spec/BPMN/20100524/MODEL"
             xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI"
             xmlns:dc="http://www.omg.org/spec/DD/20100524/DC"
             xmlns:di="http://www.omg.org/spec/DD/20100524/DI"
             xmlns:camunda="http://camunda.org/schema/1.0/bpmn"
             id="Definitions_1"
             targetNamespace="http://bpmn.io/schema/bpmn">
  <process id="Process_1" isExecutable="false">
    <startEvent id="StartEvent_1"/>
    <task id="Task_1">
      <boundaryEvent id="BoundaryEvent_1" attachedToRef="Task_1">
        <signalEventDefinition/>
      </boundaryEvent>
    </task>
    <dataObjectReference id="DataObjectReference_1" dataObjectRef="DataObject_1"/>
    <association id="Association_1" sourceRef="BoundaryEvent_1" targetRef="DataObjectReference_1"/>
  </process>
  <bpmndi:BPMNDiagram id="BPMNDiagram_1">
    <bpmndi:BPMNPlane id="BPMNPlane_1" bpmnElement="Process_1">
      <bpmndi:BPMNShape id="StartEvent_1_di" bpmnElement="StartEvent_1">
        <dc:Bounds x="173" y="102" width="36" height="36"/>
      </bpmndi:BPMNShape>
      <bpmndi:BPMNShape id="Task_1_di" bpmnElement="Task_1">
        <dc:Bounds x="240" y="80" width="100" height="80"/>
      </bpmndi:BPMNShape>
      <bpmndi:BPMNShape id="BoundaryEvent_1_di" bpmnElement="BoundaryEvent_1">
        <dc:Bounds x="340" y="100" width="36" height="36"/>
      </bpmndi:BPMNShape>
      <bpmndi:BPMNShape id="DataObjectReference_1_di" bpmnElement="DataObjectReference_1">
        <dc:Bounds x="400" y="150" width="36" height="50"/>
      </bpmndi:BPMNShape>
      <bpmndi:BPMNEdge id="Association_1_di" bpmnElement="Association_1">
        <di:waypoint x="358" y="118"/>
        <di:waypoint x="418" y="175"/>
      </bpmndi:BPMNEdge>
    </bpmndi:BPMNPlane>
  </bpmndi:BPMNDiagram>
</definitions>`;

// Import the BPMN XML
bpmnModeler.importXML(bpmnXML, function(err) {
  if (err) {
    console.error('Error importing BPMN diagram:', err);
  } else {
    console.log('BPMN diagram imported successfully');
  }
});
